user_stories:
{
  "user_stories": [
    {
      "id": 1,
      "role": "Dreamer",
      "goal": "Submit a new dream as manifest content with consent and privacy choices",
      "benefit": "Start a saved session for later latent-content exploration",
      "acceptance_criteria": [
        "I can enter dream text and confirm Freudian framing plus a non-clinical disclaimer",
        "A new session is created and saves the manifest narrative with timestamp and privacy setting"
      ]
    },
    {
      "id": 2,
      "role": "Freudian AI Analyst",
      "goal": "Generate 5–7 open-ended follow-up questions grounded in Freudian theory",
      "benefit": "Elicit free associations and clues to wish fulfillment and defenses",
      "acceptance_criteria": [
        "Questions count is 5–7 and includes at least one free-association prompt",
        "At least one prompt targets latent content/wish fulfillment and the set is stored in order on the session"
      ]
    },
    {
      "id": 3,
      "role": "Dreamer",
      "goal": "Answer the follow-up questions with autosave and optional skip",
      "benefit": "Provide associations that the analyst can use without losing progress",
      "acceptance_criteria": [
        "Each answer is saved to the session as I proceed, and I can resume later",
        "I can skip a question and still continue to the remaining prompts"
      ]
    },
    {
      "id": 4,
      "role": "Freudian AI Analyst",
      "goal": "Produce a full report synthesizing dream text and answers",
      "benefit": "Offer an exploratory interpretation distinguishing manifest vs. latent content",
      "acceptance_criteria": [
        "Report explicitly separates manifest content from hypothesized latent content and notes possible wish fulfillment, conflicts, and defenses",
        "Includes reflective suggestions and safety language that avoids diagnosis or clinical certainty, then saves as the session’s final analysis"
      ]
    },
    {
      "id": 5,
      "role": "Dreamer",
      "goal": "Review and manage past dream sessions",
      "benefit": "Track recurring themes and revisit prior interpretations over time",
      "acceptance_criteria": [
        "I can list, search/filter, and open sessions showing dream, questions, answers, and analysis",
        "I can export or delete a session and the system confirms completion"
      ]
    },
    {
      "id": 6,
      "role": "Administrator",
      "goal": "Administer users and session lifecycle with auditing and retention controls",
      "benefit": "Protect sensitive content and ensure reliable, policy-aligned operation",
      "acceptance_criteria": [
        "I can configure retention/deletion policies and enforce least-privilege access to sessions",
        "I can review audit logs and moderate flagged content or system outputs while preserving session integrity"
      ]
    }
  ]
}
